1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <meta name="color-scheme" content="light dark">
7	  <title>Animated Circle - Interactive Demo</title>
8	  <meta name="description" content="A responsive, accessible circle that changes color when clicked">
9	  <style>
10	    *,
11	    *::before,
12	    *::after {
13	      box-sizing: border-box;
14	      margin: 0;
15	      padding: 0;
16	    }
17	    :root {
18	      color-scheme: light dark;
19	      --bg: #fff;
20	      --text: #374151;
21	      --fg: #2563eb;
22	      --shadow: rgba(0, 0, 0, 0.1);
23	    }
24	    [data-color="red"] { --fg: #dc2626; }
25	    [data-color="green"] { --fg: #16a34a; }
26	    [data-color="amber"] { --fg: #d97706; }
27	    [data-color="violet"] { --fg: #7c3aed; }
28	    [data-color="cyan"] { --fg: #0891b2; }
29	    @media (prefers-color-scheme: dark) {
30	      :root {
31	        --bg: #111;
32	        --text: #d1d5db;
33	        --fg: #93c5fd;
34	        --shadow: rgba(0, 0, 0, 0.6);
35	      }
36	      [data-color="red"] { --fg: #fca5a5; }
37	      [data-color="green"] { --fg: #86efac; }
38	      [data-color="amber"] { --fg: #fcd34d; }
39	      [data-color="violet"] { --fg: #c4b5fd; }
40	      [data-color="cyan"] { --fg: #67e8f9; }
41	    }
42	    @media (prefers-contrast: more) {
43	      :root {
44	        --shadow: rgba(0, 0, 0, 0.9);
45	      }
46	    }
47	    body {
48	      min-height: 100dvh;
49	      display: grid;
50	      place-items: center;
51	      padding: 1rem;
52	      background: var(--bg);
53	      color: var(--text);
54	      font-family: system-ui, -apple-system, sans-serif;
55	    }
56	    main {
57	      width: 100%;
58	      display: flex;
59	      flex-direction: column;
60	      align-items: center;
61	      text-align: center;
62	    }
63	    button {
64	      display: block;
65	      width: min(360px, 100%);
66	      aspect-ratio: 1;
67	      border: 0;
68	      border-radius: 50%;
69	      background: none;
70	      color: var(--fg);
71	      cursor: pointer;
72	      touch-action: manipulation;
73	      -webkit-tap-highlight-color: transparent;
74	    }
75	    button:focus-visible {
76	      outline: 3px solid var(--fg);
77	      outline-offset: 8px;
78	    }
79	    svg {
80	      display: block;
81	      width: 100%;
82	      height: 100%;
83	      overflow: visible;
84	      opacity: 0.9;
85	      filter: drop-shadow(0 8px 16px var(--shadow));
86	      transition: opacity 0.3s ease;
87	    }
88	    circle {
89	      transition: fill 0.4s ease;
90	    }
91	    button:active svg,
92	    button:focus-visible svg {
93	      opacity: 1;
94	    }
95	    @media (hover: hover) {
96	      button:hover svg {
97	        opacity: 1;
98	      }
99	    }
100	    @media (prefers-reduced-motion: no-preference) {
101	      svg {
102	        transition:
103	          transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1),
104	          opacity 0.3s ease;
105	      }
106	      button:focus-visible svg {
107	        transform: scale(1.05);
108	      }
109	      button:active svg {
110	        transform: scale(0.97);
111	      }
112	    }
113	    @media (hover: hover) and (prefers-reduced-motion: no-preference) {
114	      button:hover:not(:active) svg {
115	        transform: scale(1.05);
116	      }
117	    }
118	    .status {
119	      margin-top: 2rem;
120	      font-weight: 600;
121	    }
122	    .hint {
123	      margin-top: 0.25rem;
124	      font-size: 0.875rem;
125	    }
126	  </style>
127	</head>
128	<body>
129	  <main>
130	    <button type="button" aria-label="Change circle color">
131	      <svg viewBox="0 0 100 100" aria-hidden="true" focusable="false" xmlns="http://www.w3.org/2000/svg">
132	        <circle cx="50" cy="50" r="50" fill="currentColor"/>
133	      </svg>
134	    </button>
135	    <p class="status" role="status">Blue</p>
136	    <p class="hint">Click, tap, or press Enter/Space to change the color</p>
137	  </main>
138	  <script>
139	    const button = document.querySelector('button');
140	    const status = document.querySelector('.status');
141	    const colors = ['blue', 'red', 'green', 'amber', 'violet', 'cyan'];
142	    let index = 0;
143	
144	    button.addEventListener('click', () => {
145	      index = (index + 1) % colors.length;
146	      const color = colors[index];
147	      button.dataset.color = color;
148	      status.textContent = color[0].toUpperCase() + color.slice(1);
149	    });
150	  </script>
151	</body>
152	</html>
