p='0.html';s=open(p).read()
s=s.replace("""      -webkit-tap-highlight-color: transparent;
    }""","""      -webkit-tap-highlight-color: transparent;
      transition: color 0.4s ease;
    }""",1)
s=s.replace("""    circle {
      transition: fill 0.4s ease;
    }
""","")
s=s.replace('<button type="button" aria-label="Change circle color">','<button type="button" aria-label="Change circle color" aria-describedby="status hint">')
s=s.replace('<p class="status" role="status">','<p class="status" id="status" role="status">')
s=s.replace('<p class="hint">','<p class="hint" id="hint">')
s=s.replace("Click, tap, or press Enter/Space","Click, tap, or press Enter or Space")
s=s.replace("""    const colors = ['blue', 'red', 'green', 'amber', 'violet', 'cyan'];
    let index = 0;
""","""    const colors = ['blue', 'red', 'green', 'amber', 'violet', 'cyan'];
    let index = 0;

    const label = (color) => color[0].toUpperCase() + color.slice(1);
""")
s=s.replace("status.textContent = color[0].toUpperCase() + color.slice(1);","status.textContent = label(color);")
open(p,'w').write(s)
E
grep -n "transition: color\|aria-describedby\|label(color)" 0.html

